import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"51、【震】 震下震上","description":"温公易说 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"温公易说 - 51、【震】 震下震上"},"headers":[],"relativePath":"zh/classics/wengong/052.md","filePath":"zh/classics/wengong/052.md"}'),n={name:"zh/classics/wengong/052.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><h3 id="彖曰-震-亨。震来虩虩-恐致福也。笑言哑哑-后有则也。震惊百里-惊逺而惧迩也。出可以守宗庙社稷-以为祭主也。" tabindex="-1">彖曰：震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊逺而惧迩也。出可以守宗庙社稷，以为祭主也。 <a class="header-anchor" href="#彖曰-震-亨。震来虩虩-恐致福也。笑言哑哑-后有则也。震惊百里-惊逺而惧迩也。出可以守宗庙社稷-以为祭主也。" aria-label="Permalink to “彖曰：震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊逺而惧迩也。出可以守宗庙社稷，以为祭主也。”">​</a></h3><p>震惊百里，不丧匕鬯，夫主大器者，不可以无威也。无威则民不服，民不服则所守丧矣。故曰震惊百里，不丧匕鬯。</p><h3 id="象曰-洊雷-震。君子以恐惧修省。" tabindex="-1">象曰：洊雷，震。君子以恐惧修省。 <a class="header-anchor" href="#象曰-洊雷-震。君子以恐惧修省。" aria-label="Permalink to “象曰：洊雷，震。君子以恐惧修省。”">​</a></h3><h3 id="初九-震来虩虩-后笑言哑哑-吉-象曰-震来虩虩-恐致福也。笑言哑哑-后有则也。" tabindex="-1">初九：震来虩虩，后笑言哑哑，吉 象曰：震来虩虩，恐致福也。笑言哑哑，后有则也。 <a class="header-anchor" href="#初九-震来虩虩-后笑言哑哑-吉-象曰-震来虩虩-恐致福也。笑言哑哑-后有则也。" aria-label="Permalink to “初九：震来虩虩，后笑言哑哑，吉 象曰：震来虩虩，恐致福也。笑言哑哑，后有则也。”">​</a></h3><h3 id="六二-震来厉-亿丧贝-跻于九陵-勿逐-七日得-象曰-震来厉-乘刚也。" tabindex="-1">六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得 象曰：震来厉，乘刚也。 <a class="header-anchor" href="#六二-震来厉-亿丧贝-跻于九陵-勿逐-七日得-象曰-震来厉-乘刚也。" aria-label="Permalink to “六二：震来厉，亿丧贝，跻于九陵，勿逐，七日得 象曰：震来厉，乘刚也。”">​</a></h3><h3 id="六三-震苏苏-震行无眚-象曰-震苏苏-位不当也。" tabindex="-1">六三：震苏苏，震行无眚 象曰：震苏苏，位不当也。 <a class="header-anchor" href="#六三-震苏苏-震行无眚-象曰-震苏苏-位不当也。" aria-label="Permalink to “六三：震苏苏，震行无眚 象曰：震苏苏，位不当也。”">​</a></h3><h3 id="九四-震遂泥-象曰-震遂泥-未光也。" tabindex="-1">九四：震遂泥 象曰：震遂泥，未光也。 <a class="header-anchor" href="#九四-震遂泥-象曰-震遂泥-未光也。" aria-label="Permalink to “九四：震遂泥 象曰：震遂泥，未光也。”">​</a></h3><p>泥者以阳居阴，丧其威也。</p><h3 id="六五-震往来厉-亿无丧-有事-象曰-震往来厉-危行也。" tabindex="-1">六五：震往来厉，亿无丧，有事 象曰：震往来厉，危行也。 <a class="header-anchor" href="#六五-震往来厉-亿无丧-有事-象曰-震往来厉-危行也。" aria-label="Permalink to “六五：震往来厉，亿无丧，有事 象曰：震往来厉，危行也。”">​</a></h3><p>其事在中，大无丧也。</p><h3 id="上六-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言-象曰-震索索-中未得也。虽凶无咎-畏邻戒也。" tabindex="-1">上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言 象曰：震索索，中未得也。虽凶无咎，畏邻戒也。 <a class="header-anchor" href="#上六-震索索-视矍矍-征凶。震不于其躬-于其邻-无咎。婚媾有言-象曰-震索索-中未得也。虽凶无咎-畏邻戒也。" aria-label="Permalink to “上六：震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言 象曰：震索索，中未得也。虽凶无咎，畏邻戒也。”">​</a></h3><p>震不于其躬，于其邻者，祸在彼而思在此也。楚人灭江，秦穆公为之降服。出次不举，过数曰：吾自惧也。君子曰：诗云“惟彼二国，其政不获。惟此四国，爰究爰度。”其秦穆公之谓矣。</p>',13)])])}const b=e(n,[["render",l]]);export{p as __pageData,b as default};
